'use strict';

// MODULES //

var tape = require( 'tape' );
var isStringArray = require( '@stdlib/assert/is-string-array' ).primitives;
var symbolShorthands = require( '@stdlib/plot/base/symbol-shorthands' );
var symbolAliases = require( '@stdlib/plot/base/symbol-aliases' );
var symbol2shorthand = require( '@stdlib/plot/base/symbol2shorthand' );
var symbols2shorthands = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof symbols2shorthands, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function converts an array of symbols to shorthands', function test( t ) {
	var expected;
	var actual;
	var values;
	var i;

	values = symbolAliases().concat( symbolShorthands() );
	expected = [];
	for ( i = 0; i < values.length; i++ ) {
		expected.push( symbol2shorthand( values[ i ] ) );
	}
	actual = symbols2shorthands( values );

	t.deepEqual( actual, expected, 'returns expected value' );
	t.strictEqual( isStringArray( actual ), true, 'returns an array of strings' );
	t.end();
});

tape( 'the function returns an empty array if provided an empty array', function test( t ) {
	t.deepEqual( symbols2shorthands( [] ), [], 'returns expected value' );
	t.end();
});

tape( 'if unable to resolve a shorthand for an element of the input array, the corresponding element in the output array is `null`', function test( t ) {
	var expected;
	var actual;

	expected = [ null, 'o', null ];
	actual = symbols2shorthands( [ 'beep', 'o', 'boop' ] );

	t.deepEqual( actual, expected, 'returns expected value' );
	t.end();
});
